ST.xhtml:
(* Satura nº de amostras no limite do buffer *)
nEff := nSamples;
IF nEff < 1 THEN nEff := 1; END_IF
IF nEff > 100 THEN nEff := 100; END_IF

IF xEnable THEN
    (* Insere amostra (buffer circular) *)
    arBuffer[nIndex] := rIn;
    nIndex := nIndex + 1;
    IF nIndex > nEff THEN nIndex := 1; END_IF

    IF nCount < nEff THEN nCount := nCount + 1; END_IF

    (* Média móvel com laço FOR *)
    rSum := 0.0;
    FOR i := 1 TO nCount DO
        rSum := rSum + arBuffer[i];
    END_FOR
    IF nCount > 0 THEN
        rOut := rSum / INT_TO_REAL(nCount);
    END_IF
END_IF

xValid := FALSE;
rEng   := rEngMin;   (* saída segura em falha *)

IF (rRawMax - rRawMin) <> 0.0 THEN
    rEng := rEngMin + (INT_TO_REAL(nRaw) - rRawMin) * (rEngMax - rEngMin) / (rRawMax - rRawMin);
END_IF

(* Validação simples de faixa bruta (com tolerância de under/overflow) *)
IF (nRaw >= -1000) AND (nRaw <= 28648) THEN
    xValid := TRUE;
END_IF

(* ------------------------------------------------------------- *)
(*  Pulsos de contagem: geração e auto-reset (largura fixa)      *)
(* ------------------------------------------------------------- *)
rtPulse(IN := xBottleFilled OR xBottleRejected, PT := tPulseWidth);
IF rtPulse.Q THEN
    xBottleFilled   := FALSE;
    xBottleRejected := FALSE;
END_IF

(* ------------------------------------------------------------- *)
(*  Reset global: limpa falhas e retorna à etapa IDLE            *)
(* ------------------------------------------------------------- *)
IF xReset THEN
    rtFillTO(IN := FALSE);
    rtCylTO (IN := FALSE);
    rtDrip  (IN := FALSE);
    xFault      := FALSE;
    sFaultText  := '';
    xLockCyl    := FALSE;
    xFillValve  := FALSE;
    eState      := E_DoseState.IDLE;
END_IF

(* ------------------------------------------------------------- *)
(*  Watchdog dos cilindros (tempo de movimento)                  *)
(* ------------------------------------------------------------- *)
rtCylTO(IN := (eState = E_DoseState.LOCKING) OR (eState = E_DoseState.UNLOCKING),
        PT := tCylMoveTimeout);
IF rtCylTO.Q AND NOT xFault THEN
    xFault     := TRUE;
    sFaultText := 'Timeout de movimento do cilindro';
    eState     := E_DoseState.FAULT;
END_IF

(* ------------------------------------------------------------- *)
(*  Watchdog de enchimento                                       *)
(* ------------------------------------------------------------- *)
rtFillTO(IN := (eState = E_DoseState.FILLING) OR (eState = E_DoseState.DRIPPING),
         PT := tFillTimeout);
IF rtFillTO.Q AND NOT xFault THEN
    xFault     := TRUE;
    sFaultText := 'Timeout de enchimento';
    eState     := E_DoseState.FAULT;
END_IF

(* ------------------------------------------------------------- *)
(*  Máquina de estados principal                                 *)
(* ------------------------------------------------------------- *)
CASE eState OF

    E_DoseState.IDLE:
        xLockCyl    := FALSE;
        xFillValve  := FALSE;
        xDone       := FALSE;
        xBusy       := FALSE;
        (* Só inicia se linha habilitada, ciclo ativo e garrafa presente *)
        IF xEnable AND xMachineRun AND xBottlePresent AND NOT xFault THEN
            xBusy  := TRUE;
            eState := E_DoseState.LOCKING;
        END_IF

    E_DoseState.LOCKING:
        xLockCyl := TRUE;
        IF xCylExtended THEN
            rtCylTO(IN := FALSE);
            eState := E_DoseState.FILLING;
        ELSIF NOT xBottlePresent THEN
            (* Garrafa removida durante a trava *)
            xFault     := TRUE;
            sFaultText := 'Garrafa removida durante o travamento';
            eState     := E_DoseState.FAULT;
        END_IF

    E_DoseState.FILLING:
        xLockCyl   := TRUE;
        xFillValve := TRUE;
        (* Garrafa removida durante o enchimento *)
        IF NOT xBottlePresent THEN
            xFillValve := FALSE;
            xFault     := TRUE;
            sFaultText := 'Garrafa removida durante o enchimento';
            eState     := E_DoseState.FAULT;
        ELSIF rMassActual >= rMassSetpoint THEN
            xFillValve := FALSE;
            rtDrip(IN := TRUE, PT := tDripTime);
            eState     := E_DoseState.DRIPPING;
        END_IF

    E_DoseState.DRIPPING:
        xLockCyl   := TRUE;
        xFillValve := FALSE;
        rtDrip(IN := TRUE, PT := tDripTime);
        IF rtDrip.Q THEN
            rtDrip(IN := FALSE);
            rtFillTO(IN := FALSE);
            eState := E_DoseState.UNLOCKING;
        END_IF

    E_DoseState.UNLOCKING:
        xLockCyl   := FALSE;
        xFillValve := FALSE;
        IF xCylRetracted THEN
            rtCylTO(IN := FALSE);
            xBottleFilled := TRUE;
            xDone         := TRUE;
            eState        := E_DoseState.DONE;
        END_IF

    E_DoseState.DONE:
        (* Mantém xDone até a esteira avançar; retorna a IDLE quando      *)
        (* a garrafa sai (sensor cai) ou o ciclo é reiniciado.            *)
        xLockCyl   := FALSE;
        xFillValve := FALSE;
        IF NOT xBottlePresent OR NOT xMachineRun THEN
            xDone  := FALSE;
            xBusy  := FALSE;
            eState := E_DoseState.IDLE;
        END_IF

    E_DoseState.FAULT:
        xLockCyl   := FALSE;
        xFillValve := FALSE;
        xFault     := TRUE;
        (* Linha permanece em falha até reset explícito *)
        IF NOT xBottlePresent THEN
            (* permite rejeição contabilizada pelo PRG_Main *)
        END_IF

END_CASE

(* Histerese: liga abaixo de rLow, desliga acima de rHigh *)
IF rLevelPct <= rLow THEN
    xLatched := TRUE;
ELSIF rLevelPct >= rHigh THEN
    xLatched := FALSE;
END_IF

(* Segurança: nível crítico baixo (<5%) força parada da bomba      *)
(* (evita cavitação; ajuste conforme o processo)                    *)
IF rLevelPct <= 5.0 THEN
    xLatched := FALSE;
END_IF

xPump := xLatched AND xMachineRun;

IF xResetCounters THEN
    diFilled   := 0;
    diRejected := 0;
ELSE
    FOR i := 1 TO 4 DO
        IF xFilledPulse[i] THEN
            diFilled := diFilled + 1;
        END_IF
        IF xRejectedPulse[i] THEN
            diRejected := diRejected + 1;
        END_IF
    END_FOR
END_IF

	(* ============================================================= *)
(*  1) EMERGÊNCIA E PORTA DE PROTEÇÃO — sobrepõem tudo           *)
(* ============================================================= *)
GVL_Main.xFaultGlobal := GVL_Main.xEmergStop OR NOT GVL_Main.xGuardDoor;

IF GVL_Main.xFaultGlobal THEN
    GVL_Main.xMachineRunning := FALSE;
    GVL_Main.xConveyorRun    := FALSE;
    FOR i := 1 TO 4 DO
        fbLines[i].xReset := TRUE;     (* força saída segura          *)
    END_FOR
    GVL_Main.xPumpTank := FALSE;
    GVL_Main.xLampGreen := FALSE;
    GVL_Main.xLampRed   := TRUE;
    GVL_Main.xHorn      := TRUE;
ELSE
    (* Reset normal: só com comando de reset e sem emergência *)
    IF GVL_Main.xResetPB THEN
        GVL_Main.xResetRequest := TRUE;
    END_IF
END_IF

(* Limpa pedido de reset após processamento *)
IF GVL_Main.xResetRequest AND NOT GVL_Main.xEmergStop AND GVL_Main.xGuardDoor THEN
    FOR i := 1 TO 4 DO
        fbLines[i].xReset := TRUE;
    END_FOR
    GVL_Main.xResetRequest := FALSE;
END_IF

(* ============================================================= *)
(*  2) SELEÇÃO DE RECEITA — apenas com máquina parada            *)
(* ============================================================= *)
xAllLinesEnabled := TRUE;
FOR i := 1 TO 4 DO
    IF NOT GVL_Main.axLineEnabled[i] THEN
        xAllLinesEnabled := FALSE;
    END_IF
END_FOR

nRecipeSetpoint := GVL_Main.nSelectedRecipe;
IF nRecipeSetpoint < 1 THEN nRecipeSetpoint := 1; END_IF
IF nRecipeSetpoint > 3 THEN nRecipeSetpoint := 3; END_IF

(* Receita só pode ser alterada se máquina parada e sem falhas     *)
(* (a atribuição direta já está protegida no HMI; aqui só copiamos) *)
stCurrentRecipe := GVL_Main.stRecipes[nRecipeSetpoint];

(* ============================================================= *)
(*  3) ESCALONAMENTO ANALÓGICO + MÉDIA MÓVEL                     *)
(* ============================================================= *)
FOR i := 1 TO 4 DO
    fbScaleLoad[i](
        nRaw    := GVL_Main.aiLoadCell[i],
        rRawMin := GVL_Main.rLoadCellRawMin,
        rRawMax := GVL_Main.rLoadCellRawMax,
        rEngMin := GVL_Main.rLoadCellEngMin,
        rEngMax := GVL_Main.rLoadCellEngMax
    );
    fbAvgLoad[i](
        rIn      := fbScaleLoad[i].rEng,
        nSamples := GVL_Main.nMovAvgSamples,
        xEnable  := NOT GVL_Main.xFaultGlobal
    );
    GVL_Main.arMassActual[i] := fbAvgLoad[i].rOut;
END_FOR

fbScaleTank(
    nRaw    := GVL_Main.aiTankLevel,
    rRawMin := GVL_Main.rTankRawMin,
    rRawMax := GVL_Main.rTankRawMax,
    rEngMin := GVL_Main.rTankEngMin,
    rEngMax := GVL_Main.rTankEngMax
);
fbAvgTank(
    rIn      := fbScaleTank.rEng,
    nSamples := GVL_Main.nMovAvgSamples,
    xEnable  := NOT GVL_Main.xFaultGlobal
);
GVL_Main.rTankLevelPct := fbAvgTank.rOut;

(* ============================================================= *)
(*  4) CONTROLE DE NÍVEL DO TANQUE (HISTERESE)                   *)
(* ============================================================= *)
fbTank(
    rLevelPct   := GVL_Main.rTankLevelPct,
    rLow        := GVL_Main.rTankLevelLow,
    rHigh       := GVL_Main.rTankLevelHigh,
    xMachineRun := GVL_Main.xMachineRunning
);
GVL_Main.xPumpTank := fbTank.xPump;

(* ============================================================= *)
(*  5) CICLO DE CADA LINHA DE ENCHIMENTO                         *)
(* ============================================================= *)
xAnyLineBusy  := FALSE;
xAnyLineFault := FALSE;
xAllLinesDone := TRUE;

FOR i := 1 TO 4 DO
    fbLines[i](
        xEnable         := GVL_Main.axLineEnabled[i] AND GVL_Main.xMachineRunning,
        xMachineRun     := GVL_Main.xMachineRunning,
        xBottlePresent  := GVL_Main.xBottlePresent[i],
        xCylExtended    := GVL_Main.xCylExtended[i],
        xCylRetracted   := GVL_Main.xCylRetracted[i],
        rMassActual     := GVL_Main.arMassActual[i],
        rMassSetpoint   := stCurrentRecipe.rMassSetpoint,
        tDripTime       := stCurrentRecipe.tDripTime,
        tFillTimeout    := stCurrentRecipe.tFillTimeout,
        tCylMoveTimeout := GVL_Main.tCylMoveTimeout,
        xReset          := FALSE
    );

    (* Saídas das linhas *)
    GVL_Main.xLockCyl[i]   := fbLines[i].xLockCyl;
    GVL_Main.xFillValve[i] := fbLines[i].xFillValve;

    (* Pulso de contagem e rejeição *)
    axBottleFilledPulse[i] := fbLines[i].xBottleFilled;
    (* Rejeição: falha ativa + garrafa presente = contabiliza descarte *)
    axBottleRejectPulse[i] := fbLines[i].xFault AND GVL_Main.xBottlePresent[i];

    axLineFault[i] := fbLines[i].xFault;
    axLineDone[i]  := fbLines[i].xDone;

    xAnyLineBusy  := xAnyLineBusy  OR fbLines[i].xBusy;
    xAnyLineFault := xAnyLineFault OR fbLines[i].xFault;

    (* Condição "linha concluída" considera linhas desabilitadas como prontas *)
    IF GVL_Main.axLineEnabled[i] THEN
        xAllLinesDone := xAllLinesDone AND fbLines[i].xDone;
    END_IF
END_FOR

(* ============================================================= *)
(*  6) FALHA GLOBAL AGREGADA + ALARMES                           *)
(* ============================================================= *)
IF xAnyLineFault OR GVL_Main.xFaultGlobal THEN
    GVL_Main.xLampRed   := TRUE;
    GVL_Main.xLampGreen := FALSE;
    GVL_Main.xHorn      := TRUE;
    GVL_Main.xMachineRunning := FALSE;
ELSE
    GVL_Main.xLampRed   := FALSE;
    GVL_Main.xHorn      := FALSE;
END_IF

(* ============================================================= *)
(*  7) COMANDO START/STOP                                        *)
(* ============================================================= *)
IF GVL_Main.xStartPB AND NOT GVL_Main.xFaultGlobal
   AND NOT xAnyLineFault AND GVL_Main.xGuardDoor
   AND NOT GVL_Main.xEmergStop THEN
    GVL_Main.xMachineRunning := TRUE;
END_IF

IF GVL_Main.xStopPB THEN
    GVL_Main.xMachineRunning := FALSE;
    GVL_Main.xConveyorRun    := FALSE;
END_IF

(* ============================================================= *)
(*  8) ESTEIRA: avança o próximo lote quando todas as linhas      *)
(*     habilitadas concluíram                                    *)
(* ============================================================= *)
IF GVL_Main.xMachineRunning AND NOT GVL_Main.xFaultGlobal
   AND NOT xAnyLineFault AND xAllLinesDone AND NOT xAnyLineBusy THEN
    (* Lote concluído: aciona esteira para próximo lote            *)
    IF GVL_Main.xConveyorPos THEN
        (* Ainda há lote posicionado — inicia avanço (retira lote) *)
        GVL_Main.xConveyorRun := TRUE;
    ELSE
        (* Novo lote posicionado — libera a esteira *)
        GVL_Main.xConveyorRun := FALSE;
    END_IF
END_IF

(* Se a esteira avançou e lote anterior saiu, reseta flags de DONE    *)
IF GVL_Main.xConveyorRun AND NOT GVL_Main.xConveyorPos THEN
    GVL_Main.xConveyorRun := FALSE;
END_IF

(* ============================================================= *)
(*  9) CONTADORES DE GARRAFAS                                    *)
(* ============================================================= *)
fbCounters(
    xFilledPulse   := axBottleFilledPulse,
    xRejectedPulse := axBottleRejectPulse,
    xResetCounters := FALSE
);
GVL_Main.diBottlesFilled   := fbCounters.diFilled;
GVL_Main.diBottlesRejected := fbCounters.diRejected;

(* ============================================================= *)
(* 10) SINALIZAÇÃO VERDE (máquina pronta / em ciclo)             *)
(* ============================================================= *)
IF GVL_Main.xMachineRunning AND NOT GVL_Main.xFaultGlobal AND NOT xAnyLineFault THEN
    GVL_Main.xLampGreen := TRUE;
END_IF
